const languagePicker = document.querySelector("#languagePicker");
const supportedLanguages = ["pt", "en", "es", "de", "fr"];
const textNodes = [];
const walker = document.createTreeWalker(
    document.body,
    NodeFilter.SHOW_TEXT,
    {
        acceptNode(node) {
            if (node.parentElement?.closest("script, style, svg, canvas")) {
                return NodeFilter.FILTER_REJECT;
            }
            return node.nodeValue.trim()
                ? NodeFilter.FILTER_ACCEPT
                : NodeFilter.FILTER_REJECT;
        },
    },
);

while (walker.nextNode()) {
    const node = walker.currentNode;
    textNodes.push({
        node,
        original: node.nodeValue.trim(),
        leading: node.nodeValue.match(/^\s*/)[0],
        trailing: node.nodeValue.match(/\s*$/)[0],
    });
}

const attributeNodes = [];
for (const [attribute, dictionary] of Object.entries(translatableAttributes)) {
    for (const [source, locales] of Object.entries(dictionary)) {
        const element = [...document.querySelectorAll(`[${attribute}]`)]
            .find((item) => item.getAttribute(attribute) === source);
        if (element) attributeNodes.push({ element, attribute, source, locales });
    }
}

const sourceAttributes = {
    "content": [
        ["meta[name='description']", "Ana Caroline Santos atua com cibersegurança, Red Team e pentest, e é fundadora do Prosa Tech, comunidade de educação e mentoria em tecnologia."],
        ["meta[property='og:description']", "Democratizando a cibersegurança com um toque feminino. Conteúdo técnico em linguagem acessível."],
        ["meta[property='twitter:description']", "Democratizando a cibersegurança com um toque feminino."],
    ],
    "alt": [
        [".about-photo", "Ana Caroline Santos no universo visual do Prosa Tech"],
    ],
};

const sourceAttributeNodes = [];
for (const [attribute, entries] of Object.entries(sourceAttributes)) {
    for (const [selector, source] of entries) {
        const element = document.querySelector(selector);
        if (element) sourceAttributeNodes.push({ element, attribute, source });
    }
}

const recommendationIndexes = new Map(
    [...document.querySelectorAll(".testimonial-text")].map((element, index) => [
        element,
        index,
    ]),
);

const setLanguage = (language) => {
    const locale = supportedLanguages.includes(language) ? language : "pt";
    const dictionary = translations[locale] || {};
    const metadata = localeMetadata[locale];

    for (const item of textNodes) {
        const reviewElement = item.node.parentElement?.closest(".testimonial-text");
        const reviewIndex = recommendationIndexes.get(reviewElement);
        const translation =
            dictionary[item.original] ??
            recommendationTranslations[locale]?.[reviewIndex] ??
            sharedTranslations[locale]?.[item.original] ??
            (locale === "pt" ? undefined : translations.en[item.original]);
        item.node.nodeValue = `${item.leading}${translation ?? item.original}${item.trailing}`;
    }

    for (const item of attributeNodes) {
        item.element.setAttribute(item.attribute, item.locales[locale] ?? item.source);
    }

    for (const item of sourceAttributeNodes) {
        const translation = dictionary[item.source];
        if (locale === "pt") item.element.setAttribute(item.attribute, item.source);
        else if (translation ?? translations.en[item.source]) {
            item.element.setAttribute(
                item.attribute,
                translation ?? translations.en[item.source],
            );
        }
    }

    document.documentElement.lang = metadata.html;
    document.title = metadata.title;
    document.querySelector("meta[name='description']")?.setAttribute("content", metadata.description);
    document.querySelector("meta[property='og:title']")?.setAttribute("content", metadata.socialTitle);
    document.querySelector("meta[property='twitter:title']")?.setAttribute("content", metadata.socialTitle);
    document.querySelector("meta[property='og:description']")?.setAttribute("content", metadata.socialDescription);
    document.querySelector("meta[property='twitter:description']")?.setAttribute("content", metadata.twitterDescription);
    languagePicker.value = locale;

    try {
        localStorage.setItem("portfolio-language", locale);
    } catch (error) {
        console.warn("Could not save the selected portfolio language.", error);
    }
};

let savedLanguage = null;
try {
    savedLanguage = localStorage.getItem("portfolio-language");
} catch (error) {
    console.warn("Could not read the saved portfolio language.", error);
}
const browserLanguage = navigator.language.slice(0, 2).toLowerCase();
setLanguage(savedLanguage || (supportedLanguages.includes(browserLanguage) ? browserLanguage : "pt"));
languagePicker.addEventListener("change", () => setLanguage(languagePicker.value));
